function Hash([string]$p){(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}
function Check-Ancestors([string]$p){$cursor=[IO.Path]::GetFullPath($p);while($cursor){if(Test-Path -LiteralPath $cursor){$item=Get-Item -LiteralPath $cursor;if($item.Attributes -band [IO.FileAttributes]::ReparsePoint){throw ('Reparse path not permitted: '+$cursor)}};$parent=[IO.Directory]::GetParent($cursor);if($null -eq $parent){break};$cursor=$parent.FullName}}
function Check-File([string]$p,[string]$expected){Check-Ancestors $p;if($expected -notmatch '^[0-9a-f]{64}$'){throw ('Unfrozen input: '+$p)};$item=Get-Item -LiteralPath $p;if($item.PSIsContainer -or (Hash $p) -ne $expected){throw ('Input identity changed: '+$p)}}
function Under-Root([string]$relative){$p=[IO.Path]::GetFullPath((Join-Path $taskRoot $relative));if(!$p.StartsWith($taskRoot+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Manifest path leaves workspace'};return $p}
if($args.Count -ne 0 -or (Get-Location).Path -ne $taskRoot){throw 'Fixed workspace; no arguments'}
Check-File $manifestPath $manifestHash
$manifest=Get-Content -LiteralPath $manifestPath -Raw|ConvertFrom-Json
if($manifest.schema -ne 'grim-dynasty.fixed-crowd-ready-tick-build.v1' -or $manifest.compiles -ne 2 -or $manifest.sources.Count -ne 6 -or $manifest.assemblies.Count -ne 41 -or $manifest.new_suites.Count -ne 4){throw 'Unexpected fixed plan'}
Check-Ancestors $output
if(!([IO.Path]::GetFullPath($output)).StartsWith($taskRoot+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Output outside workspace'}
if(Test-Path -LiteralPath $output){throw 'Existing output preserved; no overwrite/retry'}
function Check-Inputs {
 Check-File $compiler $compilerHash;Check-File $jsonAssembly $jsonHash;Check-File $systemCrt $systemCrtHash;Check-File $manifestPath $manifestHash
 $crt=Get-Item -LiteralPath $systemCrt;if($crt.Length -ne 1399656 -or $crt.VersionInfo.FileVersion -ne '10.0.26100.9711 (WinBuild.160101.0800)'){throw 'Frozen OWN UCRT version/size changed'}
 foreach($entry in $manifest.sources){Check-File (Under-Root $entry.path) $entry.sha256}
 foreach($entry in $manifest.evidence){Check-File (Under-Root $entry.path) $entry.sha256}
 foreach($entry in $manifest.prerequisites){Check-File (Under-Root $entry.path) $entry.sha256;$prior=Get-Content -LiteralPath (Under-Root $entry.path) -Raw|ConvertFrom-Json;if($prior.status -ne $entry.status -or $null -ne $prior.failure){throw ('Prerequisite no longer passed: '+$entry.path)}}
 foreach($entry in $manifest.assemblies){Check-File (Under-Root $entry.path) $entry.sha256;$prior=Get-Content -LiteralPath (Under-Root $entry.result) -Raw|ConvertFrom-Json;$record=@($prior.artifacts|Where-Object {$_.name -eq $entry.name -and $_.sha256 -eq $entry.sha256});if($record.Count -ne 1){throw ('Assembly lacks exact artifact receipt: '+$entry.name)}}
}
Check-Inputs
$report=[ordered]@{
 started_utc=[DateTime]::UtcNow.ToString('o');status='running';compiler=$compiler;compiler_sha256=$compilerHash
 manifest=$manifestPath;manifest_sha256=$manifestHash;source_pins=$manifest.sources;prerequisites=$manifest.prerequisites;assembly_pins=$manifest.assemblies;evidence_pins=$manifest.evidence
 steps=@();test_results=@();sample_results=@();artifacts=@();failure=$null;compiles=2
 old_test_suites_rerun=@();old_executable_entrypoints_invoked=@();original_read=$false;original_executed=$false;backend_started=$false;security_settings_changed=$false;ucrt_control_changed=$false
 frozen_ucrt_loader_recompiled=$false;camera_source_used=$false;system_library_load_requested=$false;system_library_loaded=$false;native_math_calls=0
 real_saved_ground_floor=$false;single_ready_member_two_frames=$false;actual_work_cleared=$false;full_tick=$false;physical_mouse=$false;native_scene_startup=$false;gameplay_accepted=$false
 support_boundary='One actual ready State2 Member with no replan, original Created flags0x481 and parameters, saved navigation mesh/query/corridor, explicit OWN group/actor/neighbor/skill/frame/BSS prerequisites. Engine/LastFrame gates are supplied per invocation, not generated by native frame lifecycle. Real prefix produces Work, real producer/066EE0/Floor/rotation/Entity publication returns, reached tail queries/trims, measures movement and clears Work, then the same Member starts another prefix. Goal slot28 and stuck slot38 stop after their real partial writes. Arbitrary states, replan/multi-agent ordering, native startup/event routing and physical mouse remain unclosed. The old packed DC/E0 representation supports partial writes only when the whole word is known.'
}
New-Item -ItemType Directory -Path $output|Out-Null
function Run-Step([string]$name,[string]$program,[string[]]$arguments){
 $stdout=Join-Path $output ($name+'.log');$stderr=Join-Path $output ($name+'.stderr.log');$savedPreference=$ErrorActionPreference
 try{$ErrorActionPreference='Continue';& $program @arguments 1> $stdout 2> $stderr;$ok=$?;$code=$LASTEXITCODE}finally{$ErrorActionPreference=$savedPreference}
 $report.steps += [ordered]@{name=$name;program=$program;arguments=$arguments;invocation_succeeded=$ok;exit_code=$code}
 if(!$ok -or $code -ne 0){throw "Step $name failed (invocation=$ok, exit=$code); evidence retained"}
 if((Get-Item -LiteralPath $stderr).Length -ne 0 -or ($name.StartsWith('compile-') -and (Get-Item -LiteralPath $stdout).Length -ne 0)){throw ('Unexpected diagnostics: '+$name)}
}
try{
 foreach($entry in $manifest.assemblies){Copy-Item -LiteralPath (Under-Root $entry.path) -Destination (Join-Path $output $entry.name);Check-File (Join-Path $output $entry.name) $entry.sha256}
 $references=@();foreach($entry in $manifest.assemblies){$references += '/reference:'+(Join-Path $output $entry.name)}
 $source=Join-Path $taskRoot 'src\reverse_client_actions';$library=Join-Path $output 'GrimDynasty.NavigationCrowdReadyTick.dll';$tests=Join-Path $output 'NavigationCrowdReadyTickTests.exe'
 Run-Step 'compile-crowd-ready-tick' $compiler (@('/nologo','/warn:4','/warnaserror+','/optimize+','/platform:x64','/target:library',"/out:$library")+$references+@((Join-Path $source 'NavigationCrowdTickViews.cs'),(Join-Path $source 'NavigationCrowdTickTailContracts.cs'),(Join-Path $source 'GameMovedReachedTailContracts.cs'),(Join-Path $source 'NavigationCrowdTickPrefixContracts.cs')))
 Run-Step 'compile-crowd-ready-tick-tests' $compiler (@('/nologo','/warn:4','/warnaserror+','/optimize+','/platform:x64','/target:exe','/main:NavigationCrowdTickTailTests',"/out:$tests","/reference:$library","/reference:$jsonAssembly")+$references+@((Join-Path $source 'NavigationCrowdTickTailTests.cs'),(Join-Path $source 'NavigationCrowdTickPrefixTests.cs')))
 foreach($suite in $manifest.new_suites){
  $report.system_library_load_requested=$true
  Run-Step $suite.name $tests ([string[]]@($suite.arguments))
  $summary=Get-Content -LiteralPath (Join-Path $output ($suite.name+'.log')) -Tail 1|ConvertFrom-Json
  if($summary.status -ne $suite.status -or $summary.scenarios -ne $suite.scenarios -or $summary.assertions -le 0 -or $summary.full_tick -ne $false -or $summary.physical_mouse -ne $false){throw ('Unexpected new-suite summary: '+$suite.name)}
  $report.test_results += [ordered]@{name=$suite.name;kind='new';scenarios=$summary.scenarios;assertions=$summary.assertions;native_math_calls=$summary.native_math_calls}
  $report.native_math_calls += $summary.native_math_calls
  if($suite.saved){
   $s=$summary.sample
   if($null -eq $s -or $s.tile_count -ne 9 -or $s.corridor_count -lt 2 -or $s.tile_crossings -lt 1 -or $s.flags -ne 1153 -or $s.full_tick -ne $false){throw ('Saved original flags/corridor boundary failed: '+$suite.name)}
   foreach($name in $suite.required_true){if($s.$name -ne $true){throw ('Saved path did not establish '+$name+' in '+$suite.name)}}
   if($suite.frames -eq 2){
    if($s.frames.Count -ne 2 -or $s.speed -ne 2 -or $s.minimum_bits -ne 1066192077 -or $s.elapsed_limit -ne 400 -or $s.native_math_calls -le 0){throw 'Two-frame saved Created parameters or actual rotation changed'}
    foreach($frame in $s.frames){if($frame.work_cleared -ne $true -or $frame.update_returned -ne $true -or $frame.suffix_reference -eq 0){throw 'A bounded ready frame lacks actual Update/query/cleanup'}}
   }
   $report.sample_results += [ordered]@{name=$suite.name;sample=$s}
  }
 }
 if($report.native_math_calls -le 0){throw 'No real system UCRT rotation exercised'}
 Check-Inputs;foreach($entry in $manifest.assemblies){Check-File (Join-Path $output $entry.name) $entry.sha256}
 $report.system_library_loaded=$true;$report.real_saved_ground_floor=$true;$report.single_ready_member_two_frames=$true;$report.actual_work_cleared=$true;$report.status='passed-new-bounded-ready-member-prefix-moved-tail-two-frames-only'
}catch{$report.status='failed';$report.failure=$_.Exception.Message}
finally{foreach($file in Get-ChildItem -LiteralPath $output -File){$report.artifacts += [ordered]@{name=$file.Name;bytes=$file.Length;sha256=(Hash $file.FullName)}};$report.finished_utc=[DateTime]::UtcNow.ToString('o');$report|ConvertTo-Json -Depth 16|Set-Content -LiteralPath (Join-Path $output 'result.json') -Encoding UTF8}
if($report.status -eq 'failed'){throw $report.failure}
[ordered]@{status=$report.status;test_results=$report.test_results;sample_results=$report.sample_results;result=(Join-Path $output 'result.json')}|ConvertTo-Json -Depth 12
